  tpl_flowers_signature_b: "Botanical press",
  tplText_flowers_signature_a: "The whole flower shop: the occasions as full-screen stories, Send today, the flash sale, the collections as a bento, what's loved most, Build your bouquet and kind words; every page, the petal header and bar, the account and the gift checkout in blush and plum.",
  tplText_flowers_signature_b: "The whole flower shop: the petal header, who the flowers are for, the edit as cards, Send today as a ticket, the flash sale on forest green, the collections as arches, the atelier and the price list; every page, the bar, the account and the gift checkout in sage and peach.",
