  tpl_clothes_signature_a: "LUJAIN, the boutique",
  tpl_clothes_signature_b: "NOUN, streetwear",
  tplText_clothes_signature_a: "The whole clothes shop in black and white: the search, the categories, the season's collections with the next one peeking, what's new, the deal of the day, shop the look, the collections, your size with confidence and what was seen lately; the category menu, the size guide, every page, the floating bar and the account.",
  tplText_clothes_signature_b: "The whole clothes shop as streetwear, electric blue on grey: the drop's hero, new this week, a ticker of your promises, the look of the day, the deal with its countdown, the categories, trending now and by mood; the category menu, the size guide, every page, the floating bar and the account.",
  // 209 Kids' clothes
  tpl_kids_signature_a: "TOOTA, soft pastels",
  tpl_kids_signature_b: "MINIMO, playful navy",
  tplText_kids_signature_a: "The whole kids' clothes shop in soft pastels: the search, the categories, the season's collection with the next one peeking, shopping by age, what's new, girls, boys and baby, the gift sets, school and occasions, the weekend's deals, the size finder, the most loved and your promises; the category menu, the size guide, every page, the floating bar and the account.",
  tplText_kids_signature_b: "The whole kids' clothes shop in playful navy, its sections numbered: the autumn hero, shopping by age, new this week, the look of the week, who you're shopping for, the newborn box and little gifts under a price, the occasions, the weekend's deals, the size finder and your values; the category menu, the size guide, every page, the floating bar and the account.",
