  tpl_beauty_signature_a: "VELOURS, plum and gold",
  tpl_beauty_signature_b: "NAQA LAB, the clinic",
  tplText_beauty_signature_a: "The whole cosmetics shop in plum, blush and gold: the search, the categories, the week's edits with the next one peeking, the flash deals, the best sellers, the shade finder, the skin quiz, the daily routine with ready-made routines, the care rituals, the brands and the trust strip; the category menu, the skin quiz page, every page, the floating bar and the account.",
  tplText_beauty_signature_b: "The whole cosmetics shop as a clinic, ink and cobalt on porcelain: the hero, shopping by skin and need, the skin quiz, the active ingredients, the most wanted, the routine step by step, the shade finder, the flash deals, the SPF banner and the trust strip; the category menu, the skin quiz page, every page, the floating bar and the account.",
