  // 209 Toys
  tpl_toys_signature_a: "TOOT, playful",
  tpl_toys_signature_b: "MUKAAB, Montessori",
  tplText_toys_signature_a: "The whole toy shop, playful and colourful, plum and gold on cream: the search, the categories in circles, the collections with the next one peeking, shop by age, safety first, what's new, the toy of the day, the perfect gift in 3 steps with the wraps, the most loved, gifts under 100, learn through play and the parents' guide; the category menu, every page, the floating bar and the account.",
  tplText_toys_signature_b: "The whole toy shop, calm and educational, one clear blue on grey: the search, your child's age, the explorers' collection, the categories as tiles, the science lab, trending now, the toy of the day, the birthday gift assistant with the wrapping, the top rated, gifts under 200, the newborn box and your safety promises; the category menu, every page, the floating bar and the account.",
