  // 210 Sakan (home decor), Ghurza (crochet), Rukn (furniture): their looks and ready sections.
  tpl_decor_signature_a: "SAKAN, the decor magazine",
  tplText_decor_signature_a: "The whole home decor shop in olive on warm paper: the search, the categories, the season's collections, shop by room, new arrivals, the weekend offers, complete the room with tappable products, shop by style, the most loved, gifts with a card, the seasons and reviews; the category menu, every page, the floating bar and the account.",
  tpl_decor_signature_b: "TEEN, warm earth tones",
  tplText_decor_signature_b: "The whole home decor shop in sand and oak: curated collections, the numbered best sellers, new arrivals, the house's story, shop the corner, gifts, pieces that last, a Ramadan banner and your promises; with a deep night.",
  tpl_crochet_signature_a: "GHURZA, warm handmade",
  tplText_crochet_signature_a: "The whole crochet shop in terracotta on beige: the categories, the winter collection, the custom order, new from the workshop with the days to make, the maker's story, shop by yarn, the most loved, the workshop, reviews and gift wrapping; the custom-order page and the category menu.",
  tpl_crochet_signature_b: "HABKA, colourful and playful",
  tplText_crochet_signature_b: "The whole crochet shop in plum: the greeting, design your own piece with its colours, your custom order on its way, new arrivals, the colour of the season, the toolkit, the workshops and customers' photos; the custom-order page and the category menu.",
  tpl_furniture_signature_a: "RUKN, white and wood",
  tplText_furniture_signature_a: "The whole furniture shop in linen and walnut: the rooms, the collection, your promises with installments coming soon, shop by room, new arrivals with their sizes in cm, complete sets, fabric samples, the weekend offers, book delivery and assembly, the most loved and reviews; the made-to-measure page and the category menu.",
  tpl_furniture_signature_b: "KANAF, quiet luxury",
