  tplText_mobiles_signature_a: "The whole phone shop in white, ink and cobalt: the search, the categories, the camera phone's hero with the next card peeking, trade-in, repair and warranty, the latest phones, what your old phone is worth, the deal of the day, certified used with its grades, compare before you buy, the accessories and the brands; the category menu, the trade-in and compare pages, every page, the floating bar and the account.",
  tplText_mobiles_signature_b: "The whole phone shop in deep green on warm stone: the categories as tiles, the trade-in hero, the best sellers, trade-in in three steps, renewed devices with a warranty, the deal, the bundle with installments coming soon, compare and your numbers; the category menu, the trade-in and compare pages, every page, the floating bar and the account.",
  sec_mb_trade_in: "What is your old phone worth?",
  sec_mb_trade_steps: "Trade-in in three steps",
