  // 211 Nawah, the computers and gaming shop.
  tpl_computers_signature_a: "NAWAH, white and blue",
  tpl_computers_signature_b: "SILICA, green on stone",
  tplText_computers_signature_a: "The whole computers and gaming shop in white and one strong blue: the search, the categories, the hero with the next card peeking, Build your PC part by part, the hour deals, laptops with their specs, shop by use, the gamer zone, the most wanted parts, the filters by spec, the services with installments coming soon and the reviews; the category menu, Build your PC, find by spec, every page, the floating bar and the account.",
  tplText_computers_signature_b: "The whole computers and gaming shop in deep green on stone, its sections numbered: the search with spec chips, the categories in circles, the hero, let us suggest your device, the device of the week with its spec table, the gamer corner, parts prices this week, ready builds side by side, Build your PC and the pledges with installments coming soon; the category menu, Build your PC, find by spec, every page, the floating bar and the account.",
  sec_pc_builder_card: "Build your PC, part by part",
