  tpl_electronics_signature_a: "MADAR, all in one",
  tpl_electronics_signature_b: "NABD, lime on black",
  tplText_electronics_signature_a: "The whole electronics shop in white and one deep blue: the search, the categories, the launches with the next one peeking, the services with installments coming soon, what just arrived, the deals of the day, shop by interest, the star of the season, trade-in, the brands, the best sellers and compare; the category menu, the trade-in and compare pages, every page, the floating bar and the account.",
  tplText_electronics_signature_b: "The whole electronics shop in lime on near black: where you deliver, the search with filters, the launches, the categories as photos, the deal of the day, the top five, the new arrivals, a bundle, trade-in, compare and the services; the category menu, the trade-in and compare pages, every page, the floating bar and the account.",
