  // 124.6 The premium academy in App setup and among the Studio projects.
  tplText_academy_premium: "The whole app: the home, the tab bar, the sign-in screen, the account menu and every screen's look, in navy and gold.",
  // 130.1–130.6 The Signature looks of Sofra Eats, Zad and Sahm Express, whole projects.
  tplText_food_signature_a: "The whole app as Sofra's editorial menu: tonight's dishes set huge on a photo slider, the order on its way, the restaurants, a price list and a glass bar.",
  tplText_food_signature_b: "The whole app as Sofra's bento table: the order in a gold ring, the cuisines as a photo bento, a running band of dishes and a dark floating bar.",
  tplText_marketplace_signature_a: "The whole app as Zad's market arches: green offer posters with arch photos, the departments as arches, the places near you and a glass bar.",
  tplText_marketplace_signature_b: "The whole app as Zad's night aisle: the aisle full-bleed with the order and the minutes, the departments as stories, the places as a deck.",
  tplText_delivery_signature_a: "The whole app as Sahm's waybill: the city set large, the send form as a perforated waybill with the services and prices, the shipment's stages.",
  tplText_delivery_signature_b: "The whole app as Sahm's live route: the shipment drawn on a living map, a sheet with its minutes, a command to send and the services as photos.",
  tplPicture: "{name}: its home in the app",
  kindPremiumAcademyText: "An academy with a full design: the home, the tabs, sign-in and every screen, ready for your courses",
