  tpl_travel_signature_a: "Cover story",
  tpl_travel_signature_b: "Bento atlas",
  tplText_rides_signature_a: "The whole app as Masar's living map: the ride on a map of the city, the driver on the way, the classes with their fares, and a frosted bar.",
  tplText_rides_signature_b: "The whole app as Masar's horizon: the city tilted to the horizon, “Where to?” large, the driver's minutes and the fares, and a floating pill.",
  tplText_taxi_signature_a: "The whole app as Lamha's two-ink cab: the free taxis on a map in two inks, the nearest one's minutes, the classes and the airport's set price.",
  tplText_taxi_signature_b: "The whole app as Lamha's glance radar: the free taxis' count large, a radar of the taxis around, the classes and a dock.",
  tplText_travel_signature_a: "The whole app as Safra's cover story: the resort's photo, the next trip as a boarding pass, the stays and the flights from Cairo.",
  tplText_travel_signature_b: "The whole app as Safra's bento atlas: the next trip's days, the stays as a bento, stay and flight at one price, and the departures.",
