  tplText_clothes_signature_a: "متجر الملابس كله بالأبيض والأسود: البحث، والأقسام، ومجموعات الموسم والكارت اللي بعدها باين، والجديد، وعرض اليوم، وتسوّق الإطلالة، والمجموعات، ومقاسك بثقة، واللي اتشاف مؤخرًا؛ وقايمة الأقسام، ودليل المقاسات، وكل الصفحات، والبار العايم، والحساب.",
  tplText_clothes_signature_b: "متجر الملابس كله بستايل الشارع، أزرق كهربائي على رمادي: واجهة الإصدار، وجديد الأسبوع، وشريط وعودك، وإطلالة اليوم، والعرض بعدّاده، والأقسام، والأكثر رواجًا وحسب المزاج؛ وقايمة الأقسام، ودليل المقاسات، وكل الصفحات، والبار العايم، والحساب.",
