  tplText_kids_signature_a: "متجر ملابس الأطفال كله بألوان باستيل هادية: البحث، والأقسام، ومجموعة الموسم والكارت اللي بعدها باين، والتسوّق حسب السن، والجديد، والبنات والولاد والبيبي، وأطقم الهدايا، والمدرسة والمناسبات، وعروض آخر الأسبوع، ومساعد المقاسات، والأكتر حبًّا، ووعودك؛ وقايمة الأقسام، ودليل المقاسات، وكل الصفحات، والبار العايم، والحساب.",
  tplText_kids_signature_b: "متجر ملابس الأطفال كله بكحلي مرِح وأقسام مترقّمة: واجهة الخريف، والتسوّق حسب السن، وجديد الأسبوع، وإطلالة الأسبوع، بتشتري لمين، وصندوق المولود والهدايا الصغيرة تحت سعر معيّن، والمناسبات، وعروض آخر الأسبوع، ومساعد المقاسات، وقيمك؛ وقايمة الأقسام، ودليل المقاسات، وكل الصفحات، والبار العايم، والحساب.",
