  tpl_beauty_signature_b: "NAQA LAB، ستايل العيادة",
  tplText_beauty_signature_a: "متجر التجميل كله بالبرقوقي والوردي والدهبي: البحث، والأقسام، ومختارات الأسبوع والكارت اللي بعدها باين، وعروض الساعة، والأكثر مبيعًا، ودليل الدرجات، واختبار البشرة، والروتين اليومي بروتينات جاهزة، وطقوس العناية، والماركات، وشريط الثقة؛ وقايمة الأقسام، وصفحة اختبار البشرة، وكل الصفحات، والبار العايم، والحساب.",
  tplText_beauty_signature_b: "متجر التجميل كله بستايل العيادة، كحلي وأزرق كوبالت على أبيض: الواجهة، والتسوّق حسب البشرة والاحتياج، واختبار البشرة، والمكوّنات الفعّالة، والأكثر طلبًا، والروتين خطوة بخطوة، ودليل الدرجات، وعروض الساعة، وبانر واقي الشمس، وشريط الثقة؛ وقايمة الأقسام، وصفحة اختبار البشرة، وكل الصفحات، والبار العايم، والحساب.",
