  // 209 Toys
  tpl_toys_signature_a: "TOOT، مرح وملوّن",
  tpl_toys_signature_b: "MUKAAB، مونتيسوري",
  tplText_toys_signature_a: "محل اللعب كله، مرح وملوّن، بنفسجي ودهبي على كريمي: البحث، والأقسام في دواير، والمجموعات والكارت اللي بعدها باين، والتسوّق حسب السن، وأمانهم الأول، والجديد، ولعبة اليوم، والهدية المثالية في 3 خطوات مع التغليف، والأكتر حبًّا، وهدايا تحت 100، والتعلّم باللعب، ودليل الأهل؛ وقايمة الأقسام، وكل الصفحات، والبار العايم، والحساب.",
  tplText_toys_signature_b: "محل اللعب كله، هادي وتعليمي، أزرق صافي على رمادي: البحث، وسن طفلك، ومجموعة المستكشفين، والأقسام في مربعات، ومعمل العلوم، والرائج دلوقتي، ولعبة اليوم، ومساعد هدايا عيد الميلاد مع التغليف، والأعلى تقييمًا، وهدايا تحت 200، وصندوق المولود، ووعود الأمان؛ وقايمة الأقسام، وكل الصفحات، والبار العايم، والحساب.",
  sec_ty_category_menu: "قايمة أقسام اللعب، كارت طويل الأول",
