  tpl_decor_signature_a: "SAKAN، مجلة الديكور",
  tplText_decor_signature_a: "متجر الديكور كله بالزيتوني على ورق دافي: البحث، والأقسام، ومجموعات الموسم، والتسوّق حسب الأوضة، والجديد، وعروض الويك إند، وكمّل الأوضة بمنتجات بتتداس، والتسوّق حسب الستايل، والأكتر طلبًا، والهدايا مع كارت، والمواسم، والآراء؛ وقايمة الأقسام، وكل الصفحات، والبار العايم، والحساب.",
  tpl_decor_signature_b: "TEEN، ألوان الأرض الدافية",
  tplText_decor_signature_b: "متجر الديكور كله بالرملي والبلوط: مجموعات مختارة، والأكتر مبيعًا مترقّمين، والجديد، وحكاية البيت، وتسوّق الركن، والهدايا، وقطع بتعيش، وبانر رمضان، ووعودك؛ وليل غامق.",
  tpl_crochet_signature_a: "GHURZA، شغل إيد دافي",
  tplText_crochet_signature_a: "متجر الكروشيه كله بالطوبي على البيج: الأقسام، ومجموعة الشتا، والطلب الخاص، وجديد المشغل بأيام الشغل، وحكاية الصنايعية، والتسوّق حسب الخيط، والأكتر طلبًا، والورشة، والآراء، وتغليف الهدية؛ وصفحة الطلب الخاص وقايمة الأقسام.",
  tpl_crochet_signature_b: "HABKA، ألوان ومرح",
  tplText_crochet_signature_b: "متجر الكروشيه كله بالبرقوقي: التحية، وصمّم قطعتك بألوانها، وطلبك الخاص في السكة، والجديد، ولون الموسم، والعِدّة، والورش، وصور العملا؛ وصفحة الطلب الخاص وقايمة الأقسام.",
  tpl_furniture_signature_a: "RUKN، أبيض وخشب",
  tplText_furniture_signature_a: "متجر الأثاث كله بالكتّان والجوز: الأوض، والمجموعة، ووعودك مع «التقسيط قريبًا»، والتسوّق حسب الأوضة، والجديد بمقاساته بالسنتي، والأطقم الكاملة، وعيّنات القماش، وعروض الويك إند، واحجز التوصيل والتركيب، والأكتر طلبًا، والآراء؛ وصفحة التفصيل وقايمة الأقسام.",
  tpl_furniture_signature_b: "KANAF، فخامة هادية",
  tplText_furniture_signature_b: "متجر الأثاث كله بالأخضر الغامق: الأوض، ويوصلك خلال 48 ساعة، وتسوّق المساحة كلها، وركّب كنبتك، والخدمات مع «التقسيط قريبًا»، وحجز التوصيل والتركيب، وإلهام من العملا، والمعرض؛ وصفحة التفصيل وقايمة الأقسام.",
