  tplText_mobiles_signature_a: "محل الموبايلات كله بالأبيض والأسود والأزرق: البحث، والأقسام، وواجهة موبايل الكاميرا والكارت اللي بعدها باين، والاستبدال والصيانة والضمان، وأحدث الموبايلات، وموبايلك القديم بكام، وعروض النهارده، والمستعمل المضمون بدرجاته، وقارن قبل ما تشتري، والإكسسوارات والماركات؛ وقايمة الأقسام، وصفحتين الاستبدال والمقارنة، وكل الصفحات، والبار العايم، والحساب.",
