  // 130.1–130.6 The Signature looks of Sofra Eats, Zad and Sahm Express, whole projects.
  tplText_food_signature_a: "التطبيق كله بمنيو سفرة على طريقة المجلات: أطباق الليلة بخط كبير على سلايدر صور، والطلب اللي في الطريق، والمطاعم، وقايمة أسعار، وشريط زجاجي.",
  tplText_food_signature_b: "التطبيق كله بسفرة بنتو: الطلب جوه دايرة دهبي، والمطابخ كبنتو صور، وشريط أطباق بيتحرك، وشريط عائم غامق.",
  tplText_marketplace_signature_a: "التطبيق كله بأقواس زاد: بوسترات عروض خضرا بصور على شكل قوس، والأقسام كأقواس، والأماكن القريبة، وشريط زجاجي.",
  tplText_marketplace_signature_b: "التطبيق كله بممر الليل في زاد: الممر بعرض الشاشة مع الطلب والدقايق، والأقسام كستوريز، والأماكن ككروت فوق بعض.",
  tplText_delivery_signature_a: "التطبيق كله ببوليصة سهم: اسم المدينة بخط كبير، وفورم الإرسال كبوليصة مخرّمة فيها الخدمات والأسعار، ومراحل الشحنة.",
  tplText_delivery_signature_b: "التطبيق كله بطريق سهم المباشر: الشحنة مرسومة على خريطة حية، وشيت فيه الدقايق، وزرار للإرسال، والخدمات كصور.",
