  tplText_academy_premium: "Uygulamanın tamamı: ana sayfa, sekme çubuğu, giriş ekranı, hesap menüsü ve her ekranın görünümü, lacivert ve altın renginde.",
  // 130.1–130.6 The Signature looks of Sofra Eats, Zad and Sahm Express, whole projects.
  tplText_food_signature_a: "Uygulamanın tamamı Sofra'nın editoryal menüsüyle: fotoğraf kaydırıcısında iri yazılı bu akşamın yemekleri, yoldaki sipariş, restoranlar, fiyat listesi ve cam çubuk.",
  tplText_food_signature_b: "Uygulamanın tamamı Sofra'nın bento sofrasıyla: altın halkada sipariş, fotoğraf bentosu olarak mutfaklar, akan yemek bandı ve koyu yüzen çubuk.",
  tplText_marketplace_signature_a: "Uygulamanın tamamı Zad'ın pazar kemerleriyle: kemer fotoğraflı yeşil fırsat afişleri, kemer reyonlar, yakındaki yerler ve cam çubuk.",
  tplText_marketplace_signature_b: "Uygulamanın tamamı Zad'ın gece reyonuyla: siparişle ve dakikalarla tam ekran reyon, hikâye olarak reyonlar, deste olarak yerler.",
  tplText_delivery_signature_a: "Uygulamanın tamamı Sahm'ın irsaliyesiyle: iri yazılı şehir, hizmetler ve fiyatlarla delikli irsaliye olarak gönderme formu, gönderinin aşamaları.",
  tplText_delivery_signature_b: "Uygulamanın tamamı Sahm'ın canlı rotasıyla: canlı haritada çizilen gönderi, dakikalarıyla bir sayfa, gönderme komutu ve fotoğraflı hizmetler.",
